SELECT         [O].[Quote#] AS [OrdersV2_SGQuote]         ,[O].[WO#] AS [OrdersV2_WO#]          ,[B].[JobStartDate]         ,[B].[JobFinishDate]         ,[B].[JobStartLine]          ,[A].[InputField1]         ,[A].[InputField2]              ,[A].[ProdSchedID#]         ,[A].[Quote#] AS [dtProductionSchedule_SGQuote]         ,[A].[WO#] AS [dt_ProductionSchedule_WO#]         ,[A].[Beam Line]         ,[A].[Beam Date]         ,[A].[GN Line]         ,[A].[GN Date]         ,[A].[WO Line 1]         ,[A].[Prod Date 1]         ,[A].[WO Line 2]         ,[A].[Prod Date 2]         ,[A].[Slot#]         ,[A].[Slot/Quote]         ,[A].[Prod On]         ,[A].[Prod On Time]         ,[A].[Prod Off]         ,[A].[Prod Off Time]         ,[A].[Prod PM]         ,[A].[Prod Complete]         ,[A].[Prod2 On]         ,[A].[Prod2 On Time]         ,[A].[Prod2 Off]         ,[A].[Prod2 Off Time]         ,[A].[Prod2 PM]         ,[A].[Prod2 Complete]         ,[A].[Beam On]         ,[A].[Beam Off]         ,[A].[Beam Complete]         ,[A].[Beam PM]         ,[A].[Beam Instructions]         ,[A].[GN On]         ,[A].[GN Off]         ,[A].[GN Complete]         ,[A].[GN PM]         ,[A].[GN Instructions]         ,[A].[Axle]         ,[A].[Axle On]         ,[A].[Axle Off]         ,[A].[Axle Complete]         ,[A].[Axle PM]         ,[A].[Axle Instructions]         ,[A].[Other On]         ,[A].[Other On Time]         ,[A].[Other Off]         ,[A].[Other Off Time]         ,[A].[Other Complete]         ,[A].[Other PM]         ,[A].[Other Instructions]         ,[A].[Stargate WO#]              ,[O].[Quote#] AS [dtProductionScheduleV2_SGQuote]         ,[O].[Quote Date]         ,[O].[Order Date]         ,[O].[WO#] AS [dt_ProductionScheduleV2_WO#]         ,[O].[Sales Order#]         ,[O].[Model No]         ,[O].[Width]         ,[O].[Spread]         ,[O].[DealerID]         ,[O].[Sale PersonID]         ,[O].[Price]         ,[O].[Prom Drawing]         ,[O].[Date Declined]         ,[O].[Decline/Rejected]         ,[O].[Serial Number]         ,[O].[Available Date]         ,[O].[Delivery Date]         ,[O].[Requested Delivery Date]         ,[O].[Finish Date]         ,[O].[Purchase Order]         ,[O].[PO Date]         ,[O].[US Sale]         ,[O].[Shipped Date]         ,[O].[Deck Length]         ,[O].[Invoice #]         ,[O].[Date Registered]         ,[O].[Date In Service]         ,[O].[Invoice Date]         ,[O].[GVWR]         ,[O].[Tare]         ,[O].[Slot#]         ,[O].[CompanyID]         ,[O].[Customer WO#]         ,[O].[JobAvailableLine]         ,[O].[JobAvailableScheduled]         ,[O].[JobAvailableScheduledBy]         ,(CASE WHEN [C].[Quote#] IS NULL THEN 'N' ELSE 'Y' END) AS [IsGalv]              --,[D].[COMPANY NAME]     FROM         [BWSdb].[dbo].[Orders] AS [O]     LEFT JOIN          [BWSdb].[dbo].[dtProductionSchedule] AS [A]     ON         [A].[Quote#] = [O].[Quote#]  /*     LEFT JOIN          [SysproCompanyA].[dbo].[dtProductionScheduleV2] AS [B]     ON         [B].[Quote#] = [O].[Quote#]  */       LEFT JOIN         [BWSdb].[dbo].[v_GalvanizedOptionCheck] AS [C]     ON         [C].[Quote#] = [O].[Quote#]       --LEFT JOIN     --    [BWSdb].[dbo].[DealersV2] AS [D]     --ON     --    [O].[DealerID] = [D].[ID]     WHERE   ISNULL([C].[Galvanized?], 0) = 1     --    [B].[JobFinishDate] IS NOT NULL     ORDER BY         [B].[JobFinishDate]     ;